where nombre = 'Desierto';

with bioma as (
  select id, tiles from public.biomas where nombre = 'Desierto'
),
resueltos as (
  select
    bioma.id,
    jsonb_agg(
      case
        when t.tile ? 'cofrePendiente'
          then (t.tile - 'cofrePendiente') || jsonb_build_object(
            'cofre', jsonb_build_object(
              'objetoId', (select id from public.objetos where nombre = t.tile->>'cofrePendiente' limit 1),
              'cantidad', 1
            )
          )
        else t.tile
      end
      order by t.ordinality
    ) as nuevos_tiles
  from bioma, jsonb_array_elements(bioma.tiles->'tiles') with ordinality as t(tile, ordinality)
  group by bioma.id
)
update public.biomas b
set tiles = jsonb_set(b.tiles, '{tiles}', r.nuevos_tiles)
from resueltos r
where b.id = r.id;

update public.progreso_jugador p
set posicion_q = 29, posicion_r = 29
from public.biomas b
where b.id = p.bioma_actual_id and b.nombre = 'Desierto';

update public.descubrimiento_jugador d
set casillas_descubiertas = '[]'::jsonb,
    cofres_abiertos = '[]'::jsonb,
    recursos_recolectados = '[]'::jsonb,
    puentes_construidos = '[]'::jsonb,
    cuerdas_construidas = '[]'::jsonb
from public.biomas b
where b.id = d.bioma_id and b.nombre = 'Desierto';

-- Verificación 1: río solo con vecinos cardinales de río. Debería devolver 0 filas.
with bioma as (
  select tiles from public.biomas where nombre = 'Desierto'
),
rios as (
  select (tile->>'x')::int as x, (tile->>'y')::int as y
  from bioma, jsonb_array_elements(tiles->'tiles') as tile
  where tile->>'tipo' = 'rio'
)
select r.x, r.y
from rios r
where not exists (
  select 1 from rios v
  where (v.x = r.x and v.y = r.y - 1)
     or (v.x = r.x + 1 and v.y = r.y)
     or (v.x = r.x and v.y = r.y + 1)
     or (v.x = r.x - 1 and v.y = r.y)
);

-- Verificación 2: no debería quedar ningún "cofrePendiente" sin resolver.
select tile
from public.biomas, jsonb_array_elements(tiles->'tiles') as tile
where nombre = 'Desierto'
  and tile ? 'cofrePendiente';

-- Verificación 3: conteo de elementos.
select
  count(*) filter (where tile->>'tipo' = 'arbol') as arboles,
  count(*) filter (where tile->>'tipo' = 'cactus') as cactus,
  count(*) filter (where tile->>'recurso' = 'piedra') as piedra,
  count(*) filter (where tile->>'recurso' = 'lana') as lana,
  count(*) filter (where tile ? 'cofre') as cofres,
  count(*) filter (where tile->>'tipo' = 'roca_clase') as roca_clase,
  count(*) filter (where tile->>'tipo' = 'enemigo') as enemigos,
  count(*) filter (where tile->>'tipo' = 'jefe_final') as jefe_final
from public.biomas, jsonb_array_elements(tiles->'tiles') as tile
where nombre = 'Desierto';
